import compression from 'compression';
import express, { type Application } from 'express';
import { pinoHttp } from 'pino-http';

import { healthRouter } from '@/api/health/health.routes.js';
import { v1Router } from '@/api/v1/index.js';
import { errorMiddleware } from '@/middleware/error.middleware.js';
import { createRateLimitMiddleware } from '@/middleware/ratelimit.middleware.js';
import { applySecurityMiddleware } from '@/middleware/security.middleware.js';

import { config } from './config.js';
import { logger } from './logger.js';

/**
 * Express application factory.
 *
 * Design: App factory function (not singleton module) allows us to create
 * fresh app instances for testing without side effects from module-level state.
 *
 * Middleware order is intentional and must not be changed:
 * 1. Security headers (helmet, CORS, HPP) — first, before any processing
 * 2. Body parsing — before routes read req.body
 * 3. Compression — before response is sent
 * 4. Request logging — before routes for accurate timing
 * 5. Rate limiting — before expensive route handlers
 * 6. Routes — business logic
 * 7. Error handler — must be LAST, catches all errors from routes
 */
export function createApp(): Application {
  const app = express();

  // ── Trust proxy (required for rate limiting behind Nginx/load balancer) ─
  app.set('trust proxy', 1);

  // ── Security middleware (helmet, CORS, HPP) ─────────────────────────────
  applySecurityMiddleware(app);

  // ── Body parsing ─────────────────────────────────────────────────────────
  app.use(express.json({ limit: '10mb' }));
  app.use(express.urlencoded({ extended: true, limit: '10mb' }));

  // ── Compression ──────────────────────────────────────────────────────────
  app.use(compression());

  // ── Request logging (Pino HTTP) ──────────────────────────────────────────
  app.use(
    pinoHttp({
      logger,
      // Auto-generate requestId, propagate to all child logs
      genReqId: (req) => {
        return (req.headers['x-request-id'] as string | undefined) ?? crypto.randomUUID();
      },
      customLogLevel: (req, res, error) => {
        if (error !== undefined || res.statusCode >= 500) return 'error';
        if (res.statusCode >= 400) return 'warn';
        return 'info';
      },
      customSuccessMessage: (req, res) =>
        `${req.method} ${req.url} ${res.statusCode}`,
      customErrorMessage: (req, res, error) =>
        `${req.method} ${req.url} ${res.statusCode} - ${error.message}`,
      // Don't log health check endpoints (too noisy)
      autoLogging: {
        ignore: (req) => req.url === '/health' || req.url === '/health/ready',
      },
    }),
  );

  // ── Global rate limiting ─────────────────────────────────────────────────
  app.use(createRateLimitMiddleware('global'));

  // ── Routes ───────────────────────────────────────────────────────────────
  app.use('/health', healthRouter);
  app.use('/api/v1', v1Router);

  // ── 404 handler ──────────────────────────────────────────────────────────
  app.use((req, res) => {
    res.status(404).json({
      success: false,
      error: {
        code: 'NOT_FOUND',
        message: `Cannot ${req.method} ${req.path}`,
        requestId: (req as express.Request & { id?: string }).id ?? 'unknown',
        timestamp: new Date().toISOString(),
      },
    });
  });

  // ── Global error handler — MUST be last ──────────────────────────────────
  app.use(errorMiddleware);

  return app;
}

import { Redis } from 'ioredis';

import { config } from './config.js';
import { createModuleLogger } from './logger.js';

const log = createModuleLogger('Redis');

/**
 * Redis client singleton with connection lifecycle management.
 *
 * Design decisions:
 * - Single shared connection for all Redis operations (BullMQ creates its own connections)
 * - Automatic reconnection with exponential backoff — don't crash on transient failures
 * - lazyConnect: true — connection only established when first command is issued
 * - enableReadyCheck: true — waits for Redis to be fully ready before accepting commands
 * - maxRetriesPerRequest: null for BullMQ clients (required by BullMQ)
 */

let redisClient: Redis | null = null;

export function createRedisClient(options?: { maxRetriesPerRequest?: null }): Redis {
  const client = new Redis(config.REDIS_URL, {
    password: config.REDIS_PASSWORD ?? undefined,
    db: config.REDIS_DB,
    lazyConnect: true,
    enableReadyCheck: true,
    maxRetriesPerRequest: options?.maxRetriesPerRequest ?? 3,
    retryStrategy: (times: number) => {
      const delay = Math.min(times * 500, 5000); // Max 5s backoff
      log.warn({ attempt: times, delayMs: delay }, 'Redis reconnecting...');
      return delay;
    },
    reconnectOnError: (error: Error) => {
      const targetErrors = ['READONLY', 'ECONNRESET', 'ECONNREFUSED'];
      return targetErrors.some((e) => error.message.includes(e));
    },
  });

  client.on('connect', () => log.info('Redis connected'));
  client.on('ready', () => log.info('Redis ready'));
  client.on('error', (error: Error) => log.error({ err: error }, 'Redis error'));
  client.on('close', () => log.warn('Redis connection closed'));
  client.on('reconnecting', () => log.info('Redis reconnecting'));

  return client;
}

/**
 * Singleton Redis client for general application use.
 */
export function getRedisClient(): Redis {
  if (redisClient === null) {
    redisClient = createRedisClient();
  }
  return redisClient;
}

/**
 * Connect the Redis client.
 * Called during application startup.
 */
export async function connectRedis(): Promise<void> {
  const client = getRedisClient();
  await client.connect();
  log.info('Redis client connected successfully');
}

/**
 * Graceful Redis disconnect.
 * Called during application shutdown.
 */
export async function disconnectRedis(): Promise<void> {
  if (redisClient !== null) {
    await redisClient.quit();
    redisClient = null;
    log.info('Redis disconnected');
  }
}

/**
 * Redis health check.
 */
export async function checkRedisHealth(): Promise<{
  status: 'healthy' | 'unhealthy';
  latencyMs: number;
  error?: string;
}> {
  const start = Date.now();
  try {
    const client = getRedisClient();
    await client.ping();
    return { status: 'healthy', latencyMs: Date.now() - start };
  } catch (error) {
    return {
      status: 'unhealthy',
      latencyMs: Date.now() - start,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
}

import http from 'node:http';

import { prisma } from '@microintern/database';

import { createApp } from './app.js';
import { config } from './config.js';
import { createContainer } from './container.js';
import { connectDatabase } from './database.js';
import { logger } from './logger.js';
import { connectRedis, disconnectRedis } from './redis.js';

/**
 * HTTP server bootstrap and graceful shutdown.
 *
 * Startup sequence:
 * 1. Validate config (happens on import of config.ts)
 * 2. Connect database
 * 3. Connect Redis
 * 4. Initialize DI container
 * 5. Create Express app
 * 6. Start HTTP server
 *
 * Shutdown sequence (SIGTERM / SIGINT):
 * 1. Stop accepting new connections
 * 2. Wait for in-flight requests to complete (30s timeout)
 * 3. Disconnect Redis
 * 4. Disconnect database
 * 5. Exit process
 *
 * This ensures zero-downtime deployments when used with a load balancer.
 */

async function bootstrap(): Promise<void> {
  logger.info({ env: config.NODE_ENV, version: config.APP_VERSION }, '🚀 Starting MicroIntern API');

  // ── Infrastructure connections ────────────────────────────────────────────
  await connectDatabase();
  await connectRedis();

  // ── Initialize DI container ───────────────────────────────────────────────
  createContainer();
  logger.info('DI container initialized');

  // ── Create Express application ────────────────────────────────────────────
  const app = createApp();
  const server = http.createServer(app);

  // ── Start server ──────────────────────────────────────────────────────────
  server.listen(config.API_PORT, config.API_HOST, () => {
    logger.info(
      {
        host: config.API_HOST,
        port: config.API_PORT,
        url: config.API_BASE_URL,
      },
      `✅ API server listening`,
    );
  });

  // ── Graceful shutdown ─────────────────────────────────────────────────────
  const SHUTDOWN_TIMEOUT_MS = 30_000;

  async function gracefulShutdown(signal: string): Promise<void> {
    logger.info({ signal }, '⏹️ Graceful shutdown initiated');

    // Stop accepting new connections
    server.close(async () => {
      logger.info('HTTP server closed');
    });

    // Force exit after timeout
    const forceExit = setTimeout(() => {
      logger.error('Graceful shutdown timeout — forcing exit');
      process.exit(1);
    }, SHUTDOWN_TIMEOUT_MS);

    forceExit.unref(); // Don't keep process alive for this timer

    try {
      await disconnectRedis();
      await prisma.$disconnect();
      logger.info('✅ Clean shutdown complete');
      process.exit(0);
    } catch (error) {
      logger.error({ err: error }, 'Error during shutdown');
      process.exit(1);
    }
  }

  process.on('SIGTERM', () => void gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => void gracefulShutdown('SIGINT'));

  // ── Unhandled rejection / exception handlers ──────────────────────────────
  process.on('unhandledRejection', (reason, promise) => {
    logger.fatal({ reason, promise }, '🚨 Unhandled Promise Rejection — shutting down');
    void gracefulShutdown('unhandledRejection');
  });

  process.on('uncaughtException', (error) => {
    logger.fatal({ err: error }, '🚨 Uncaught Exception — shutting down');
    void gracefulShutdown('uncaughtException');
  });
}

// ── Entry point ────────────────────────────────────────────────────────────
bootstrap().catch((error: unknown) => {
  console.error('Fatal error during startup:', error);
  process.exit(1);
});

import { config, aiFallbackProviders } from '@/core/config.js';

import { AIFallbackEngine } from './AIFallbackEngine.js';
import { AISafetyLayer } from './AISafetyLayer.js';
import { GeminiProvider } from './providers/GeminiProvider.js';
import { GroqProvider } from './providers/GroqProvider.js';
import { OllamaProvider } from './providers/OllamaProvider.js';
import { OpenRouterProvider } from './providers/OpenRouterProvider.js';

import type { IAIProvider } from './interfaces/IAIProvider.js';
import type { AIProvider } from '@microintern/shared';

export { AIFallbackEngine } from './AIFallbackEngine.js';
export { AISafetyLayer } from './AISafetyLayer.js';
export { compilePrompt, PROMPTS } from './PromptManager.js';
export type { CompiledPrompt, PromptTemplate } from './PromptManager.js';
export type { IAIProvider, AICompletionRequest, AICompletionResponse } from './interfaces/IAIProvider.js';

/**
 * AI Gateway singleton factory.
 * Creates the fallback engine with providers in configured priority order.
 */
let gatewayInstance: AIFallbackEngine | null = null;
let safetyInstance: AISafetyLayer | null = null;

const providerMap: Record<string, () => IAIProvider> = {
  groq: () => new GroqProvider(),
  openrouter: () => new OpenRouterProvider(),
  gemini: () => new GeminiProvider(),
  ollama: () => new OllamaProvider(),
};

export function createAIGateway(): AIFallbackEngine {
  if (gatewayInstance !== null) return gatewayInstance;

  // Build provider list: primary first, then fallbacks
  const providerOrder = [config.AI_PRIMARY_PROVIDER, ...aiFallbackProviders];
  const seen = new Set<string>();
  const providers: IAIProvider[] = [];

  for (const providerName of providerOrder) {
    if (seen.has(providerName)) continue;
    seen.add(providerName);
    const factory = providerMap[providerName];
    if (factory !== undefined) {
      providers.push(factory());
    }
  }

  gatewayInstance = new AIFallbackEngine(providers);
  return gatewayInstance;
}

export function getAIGateway(): AIFallbackEngine {
  if (gatewayInstance === null) {
    return createAIGateway();
  }
  return gatewayInstance;
}

export function getAISafetyLayer(): AISafetyLayer {
  if (safetyInstance === null) {
    safetyInstance = new AISafetyLayer();
  }
  return safetyInstance;
}

import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import Handlebars from 'handlebars';
import nodemailer from 'nodemailer';

import { config } from '@/core/config.js';
import { createModuleLogger } from '@/core/logger.js';

import type { Transporter, SendMailOptions } from 'nodemailer';

const log = createModuleLogger('EmailService');

const TEMPLATES_DIR = join(process.cwd(), 'src', 'emails', 'templates');

/**
 * Email Service — Nodemailer with Handlebars templating.
 *
 * Transport selection:
 * - smtp: Used in development (MailHog) and production (Resend SMTP)
 * - resend: Direct Resend API (faster, better analytics)
 *
 * All emails use Handlebars HTML templates.
 * Template cache prevents re-reading files on every send.
 */
export class EmailService {
  private readonly transporter: Transporter;
  private readonly templateCache = new Map<string, HandlebarsTemplateDelegate>();
  private readonly templatesDir = TEMPLATES_DIR;

  constructor() {
    this.transporter = this.createTransporter();
  }

  private createTransporter(): Transporter {
    return nodemailer.createTransport({
      host: config.SMTP_HOST,
      port: config.SMTP_PORT,
      secure: config.SMTP_SECURE,
      auth:
        config.SMTP_USER !== undefined && config.SMTP_PASS !== undefined
          ? { user: config.SMTP_USER, pass: config.SMTP_PASS }
          : undefined,
    });
  }

  /**
   * Send a templated email.
   */
  async sendTemplated<T extends Record<string, unknown>>(options: {
    to: string | string[];
    subject: string;
    templateId: string;
    variables: T;
    replyTo?: string;
  }): Promise<void> {
    const html = await this.renderTemplate(options.templateId, options.variables);

    await this.send({
      to: Array.isArray(options.to) ? options.to.join(', ') : options.to,
      subject: options.subject,
      html,
      replyTo: options.replyTo,
    });
  }

  /**
   * Send a raw email (for simple transactional messages).
   */
  async send(options: {
    to: string;
    subject: string;
    html: string;
    text?: string;
    replyTo?: string;
  }): Promise<void> {
    const mailOptions: SendMailOptions = {
      from: `"${config.EMAIL_FROM_NAME}" <${config.EMAIL_FROM_ADDRESS}>`,
      to: options.to,
      subject: options.subject,
      html: options.html,
      text: options.text ?? this.stripHtml(options.html),
      replyTo: options.replyTo,
    };

    try {
      const info = await this.transporter.sendMail(mailOptions);
      log.info({ messageId: info.messageId, to: options.to }, 'Email sent');
    } catch (error) {
      log.error({ err: error, to: options.to }, 'Email send failed');
      throw error;
    }
  }

  /**
   * Verify SMTP connection — used in health checks.
   */
  async verifyConnection(): Promise<boolean> {
    try {
      await this.transporter.verify();
      return true;
    } catch {
      return false;
    }
  }

  private async renderTemplate<T extends Record<string, unknown>>(
    templateId: string,
    variables: T,
  ): Promise<string> {
    let template = this.templateCache.get(templateId);

    if (template === undefined) {
      const templatePath = join(TEMPLATES_DIR, `${templateId}.hbs`);
      const source = await readFile(templatePath, 'utf-8');
      template = Handlebars.compile(source);
      this.templateCache.set(templateId, template);
    }

    return template(variables);
  }

  private stripHtml(html: string): string {
    return html.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
  }
}

// Singleton instance
let emailService: EmailService | null = null;

export function getEmailService(): EmailService {
  if (emailService === null) {
    emailService = new EmailService();
  }
  return emailService;
}

import { QUEUE_NAMES } from '@microintern/shared';
import { Queue, Worker, QueueEvents, type Job, type WorkerOptions } from 'bullmq';

import { config } from '@/core/config.js';
import { createModuleLogger } from '@/core/logger.js';
import { createRedisClient } from '@/core/redis.js';

const log = createModuleLogger('QueueRegistry');

/**
 * BullMQ connection options.
 * maxRetriesPerRequest: null is REQUIRED for BullMQ connections.
 */
const bullMQConnection = () => createRedisClient({ maxRetriesPerRequest: null });

/**
 * Default job options applied to all queues.
 */
const defaultJobOptions = {
  attempts: 3,
  backoff: {
    type: 'exponential' as const,
    delay: 5000, // 5s initial, then 10s, 20s
  },
  removeOnComplete: {
    age: 24 * 3600, // Keep completed jobs for 24h
    count: 1000,    // Keep last 1000 completed jobs
  },
  removeOnFail: {
    age: 7 * 24 * 3600, // Keep failed jobs for 7 days (for debugging)
  },
};

/**
 * Queue registry — single source of truth for all BullMQ queues.
 *
 * Each queue has:
 * - A typed Queue instance for adding jobs
 * - Shared connection with maxRetriesPerRequest: null (BullMQ requirement)
 * - Standard retry and retention policies
 */
export const queues = {
  email: new Queue(QUEUE_NAMES.EMAIL, {
    connection: bullMQConnection(),
    defaultJobOptions,
  }),

  aiEvaluation: new Queue(QUEUE_NAMES.AI_EVALUATION, {
    connection: bullMQConnection(),
    defaultJobOptions: {
      ...defaultJobOptions,
      attempts: 2, // AI evaluations get fewer retries (expensive)
    },
  }),

  notification: new Queue(QUEUE_NAMES.NOTIFICATION, {
    connection: bullMQConnection(),
    defaultJobOptions,
  }),

  storageProcessing: new Queue(QUEUE_NAMES.STORAGE_PROCESSING, {
    connection: bullMQConnection(),
    defaultJobOptions,
  }),

  audit: new Queue(QUEUE_NAMES.AUDIT, {
    connection: bullMQConnection(),
    defaultJobOptions: {
      ...defaultJobOptions,
      attempts: 5, // Audit logs are critical — more retries
    },
  }),
};

/**
 * Base worker factory.
 * Feature teams call this to create typed workers for their queues.
 *
 * @example
 * const emailWorker = createWorker(
 *   QUEUE_NAMES.EMAIL,
 *   async (job) => { await sendEmail(job.data); },
 *   { concurrency: config.QUEUE_CONCURRENCY_EMAIL },
 * );
 */
export function createWorker<T>(
  queueName: string,
  processor: (job: Job<T>) => Promise<void>,
  options?: Partial<WorkerOptions>,
): Worker<T> {
  const worker = new Worker<T>(
    queueName,
    processor,
    {
      connection: bullMQConnection(),
      concurrency: 5,
      ...options,
    },
  );

  worker.on('completed', (job) => {
    log.info({ queue: queueName, jobId: job.id }, 'Job completed');
  });

  worker.on('failed', (job, error) => {
    log.error(
      { queue: queueName, jobId: job?.id, err: error, attempts: job?.attemptsMade },
      'Job failed',
    );
  });

  worker.on('stalled', (jobId) => {
    log.warn({ queue: queueName, jobId }, 'Job stalled');
  });

  log.info({ queue: queueName }, 'Worker started');
  return worker;
}

/**
 * Type-safe job data interfaces — one per queue.
 * Feature teams extend these as needed.
 */

export type EmailJobData = {
  to: string;
  templateId: string;
  variables: Record<string, unknown>;
