import { REDIS_KEYS } from '@microintern/shared';
import jwt from 'jsonwebtoken';

import { config } from '@/core/config.js';
import { getRedisClient } from '@/core/redis.js';
import { UnauthorizedError } from '@/shared/errors/index.js';

import type { JwtAccessPayload, AuthenticatedUser } from '@microintern/shared';
import type { Request, Response, NextFunction } from 'express';

/**
 * Extend Express Request to include authenticated user.
 * This augmentation is available throughout the application.
 */
declare global {
  namespace Express {
    interface Request {
      user?: AuthenticatedUser;
      sessionId?: string;
    }
  }
}

/**
 * Authentication middleware — verifies JWT access token.
 *
 * Design:
 * - Access token is expected in Authorization header: "Bearer <token>"
 * - Verifies signature, expiry, issuer, and audience
 * - Checks Redis to ensure session has not been revoked
 * - Attaches typed user context to req.user
 *
 * Session revocation: When a user logs out or changes password,
 * all their sessions are removed from Redis. Even if an access token
 * is technically valid (not expired), it will fail the Redis check.
 * This is the key advantage of Redis-backed sessions over pure JWT.
 *
 * Note: Access tokens are short-lived (15min) — the Redis check
 * is only a secondary safety net for immediate invalidation scenarios.
 */
export async function authMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): Promise<void> {
  try {
    const token = extractBearerToken(req);

    if (token === null) {
      throw new UnauthorizedError('Authentication token required', 'AUTH_TOKEN_INVALID');
    }

    let payload: JwtAccessPayload;
    try {
      payload = jwt.verify(token, config.JWT_ACCESS_SECRET, {
        issuer: config.JWT_ISSUER,
        audience: config.JWT_AUDIENCE,
        algorithms: ['HS256'],
      }) as JwtAccessPayload;
    } catch (error) {
      if (error instanceof jwt.TokenExpiredError) {
        throw new UnauthorizedError('Access token expired', 'AUTH_TOKEN_EXPIRED');
      }
      throw new UnauthorizedError('Invalid access token', 'AUTH_TOKEN_INVALID');
    }

    // Verify session is still active in Redis
    const redis = getRedisClient();
    const sessionKey = REDIS_KEYS.refreshToken(payload.sub, payload.sessionId);
    const sessionExists = await redis.exists(sessionKey);

    if (sessionExists === 0) {
      throw new UnauthorizedError('Session expired or revoked', 'AUTH_TOKEN_REVOKED');
    }

    // Attach authenticated user to request
    req.user = {
      id: payload.sub,
      email: payload.email,
      role: payload.role,
      companyId: payload.companyId,
      sessionId: payload.sessionId,
    };

    next();
  } catch (error) {
    next(error);
  }
}

/**
 * Optional auth middleware — attaches user if token present, but doesn't
 * require authentication. Useful for public endpoints that personalize
 * content for logged-in users.
 */
export async function optionalAuthMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): Promise<void> {
  const token = extractBearerToken(req);
  if (token === null) {
    next();
    return;
  }

  try {
    const payload = jwt.verify(token, config.JWT_ACCESS_SECRET, {
      issuer: config.JWT_ISSUER,
      audience: config.JWT_AUDIENCE,
      algorithms: ['HS256'],
    }) as JwtAccessPayload;

    req.user = {
      id: payload.sub,
      email: payload.email,
      role: payload.role,
      companyId: payload.companyId,
      sessionId: payload.sessionId,
    };
  } catch {
    // Token invalid — proceed as unauthenticated (no error thrown)
  }

  next();
}

function extractBearerToken(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return null;
  }
  const token = authHeader.slice(7).trim();
  return token.length > 0 ? token : null;
}

import { rateLimit } from 'express-rate-limit';
import { RedisStore } from 'rate-limit-redis';

import { config } from '@/core/config.js';
import { getRedisClient } from '@/core/redis.js';
import { RateLimitError } from '@/shared/errors/index.js';
import { ResponseFormatter } from '@/shared/response/ResponseFormatter.js';

import type { Request, Response, NextFunction } from 'express';

type RateLimitContext = 'global' | 'auth' | 'ai' | 'upload';

const rateLimitConfigs: Record<RateLimitContext, { windowMs: number; max: number; message: string }> = {
  global: {
    windowMs: config.RATE_LIMIT_WINDOW_MS,
    max: config.RATE_LIMIT_MAX_REQUESTS,
    message: 'Too many requests. Please slow down.',
  },
  auth: {
    windowMs: config.RATE_LIMIT_WINDOW_MS,
    max: config.RATE_LIMIT_AUTH_MAX_REQUESTS,
    message: 'Too many authentication attempts. Please wait before trying again.',
  },
  ai: {
    windowMs: 60_000,
    max: 20,
    message: 'AI request limit exceeded. Please try again in a minute.',
  },
  upload: {
    windowMs: 60_000,
    max: 10,
    message: 'Upload limit exceeded. Please wait before uploading again.',
  },
};

/**
 * Create a rate limiter middleware for a given context.
 *
 * Design: Redis-backed rate limiting for distributed deployments.
 * Each context (global, auth, ai, upload) has separate limits.
 * Rate limit headers are always sent so clients can self-throttle.
 *
 * Key format: rl:{context}:{ip} — unique per IP per context.
 */
export function createRateLimitMiddleware(context: RateLimitContext) {
  const contextConfig = rateLimitConfigs[context];

  return rateLimit({
    windowMs: contextConfig.windowMs,
    max: contextConfig.max,
    standardHeaders: 'draft-7', // `RateLimit-*` headers per RFC 6585
    legacyHeaders: false,
    keyGenerator: (req: Request): string => {
      // Use authenticated user ID if available, otherwise IP
      const userId = (req as Request & { user?: { id: string } }).user?.id;
      const ip = req.ip ?? req.socket.remoteAddress ?? 'unknown';
      return `rl:${context}:${userId ?? ip}`;
    },
    store: new RedisStore({
      sendCommand: async (...args: string[]) => {
        return (await getRedisClient().call(args[0] ?? '', ...args.slice(1))) as any;
      },
    }),
    handler: (req: Request, res: Response) => {
      const error = new RateLimitError(contextConfig.message);
      ResponseFormatter.error(res, {
        statusCode: error.statusCode,
        code: error.code,
        message: error.message,
      });
    },
    skip: (req: Request): boolean => {
      // Skip rate limiting for health checks
      return req.path === '/health' || req.path === '/health/ready';
    },
  });
}

/**
 * Stricter rate limiter for auth endpoints.
 * Applied per-route, not globally.
 */
export const authRateLimiter = createRateLimitMiddleware('auth');

/**
 * Rate limiter for AI endpoints.
 */
export const aiRateLimiter = createRateLimitMiddleware('ai');

/**
 * Rate limiter for upload endpoints.
 */
export const uploadRateLimiter = createRateLimitMiddleware('upload');

import { ValidationError } from '@/shared/errors/index.js';

import type { Request, Response, NextFunction } from 'express';
import type { ZodSchema, ZodError } from 'zod';


type ValidationTarget = 'body' | 'query' | 'params';

/**
 * Zod validation middleware factory.
 *
 * Design: Middleware validates request data against a Zod schema and replaces
 * the request data with the parsed (transformed) output. This ensures that by
 * the time a controller reads req.body, the data is already typed, transformed,
 * and validated — no additional guards needed in business logic.
 *
 * Validation errors are thrown as ValidationError (422) with field-level details.
 * This ensures consistent error format regardless of which endpoint fails.
 *
 * @example
 * router.post('/register',
 *   validate('body', RegisterSchema),
 *   authController.register,
 * );
 */
export function validate<T>(target: ValidationTarget, schema: ZodSchema<T>) {
  return (req: Request, _res: Response, next: NextFunction): void => {
    const result = schema.safeParse(req[target]);

    if (!result.success) {
      const details = formatZodErrors(result.error);
      next(new ValidationError('Request validation failed', details));
      return;
    }

    // Replace request data with parsed output (applies Zod transforms)
    (req[target] as unknown) = result.data;
    next();
  };
}

/**
 * Format Zod validation errors into the API error detail format.
 */
function formatZodErrors(error: ZodError): Record<string, unknown>[] {
  return error.issues.map((issue) => ({
    field: issue.path.join('.') || 'root',
    message: issue.message,
    code: issue.code,
  }));
}

/**
 * Validate multiple targets at once.
 * Order: params → query → body (least to most specific).
 *
 * @example
 * router.get('/:id',
 *   validateAll({
 *     params: ParamsSchema,
 *     query: ListQuerySchema,
 *   }),
 *   controller.list,
 * );
 */
export function validateAll(schemas: Partial<Record<ValidationTarget, ZodSchema>>): (
  req: Request,
  res: Response,
  next: NextFunction,
) => void {
  const validationOrder: ValidationTarget[] = ['params', 'query', 'body'];

  return (req: Request, res: Response, next: NextFunction): void => {
    for (const target of validationOrder) {
      const schema = schemas[target];
      if (schema === undefined) continue;

      const result = schema.safeParse(req[target]);
      if (!result.success) {
        const details = formatZodErrors(result.error);
        next(new ValidationError(`Validation failed for ${target}`, details));
        return;
      }
      (req[target] as unknown) = result.data;
    }
    next();
  };
}

import { EmailSchema, PasswordSchema, NameSchema, UuidSchema } from '@microintern/shared';
import { z } from 'zod';

/**
 * Auth module DTOs (Data Transfer Objects).
 *
 * These schemas serve dual purpose:
 * 1. Zod validation at the HTTP layer (validate middleware)
 * 2. Type inference for use case inputs/outputs
 *
 * DTOs never leak domain entities to the outside world.
 * Domain entities never have Zod decorators.
 */

// ── Registration ─────────────────────────────────────────────────────────────

export const RegisterCandidateSchema = z.object({
  email: EmailSchema,
  password: PasswordSchema,
  firstName: NameSchema,
  lastName: NameSchema,
});

export type RegisterCandidateDto = z.infer<typeof RegisterCandidateSchema>;

export const RegisterCompanyOwnerSchema = z.object({
  email: EmailSchema,
  password: PasswordSchema,
  firstName: NameSchema,
  lastName: NameSchema,
  companyName: z.string().min(2).max(255).trim(),
  companyWebsite: z.string().url().optional(),
});

export type RegisterCompanyOwnerDto = z.infer<typeof RegisterCompanyOwnerSchema>;

// ── Login ─────────────────────────────────────────────────────────────────────

export const LoginSchema = z.object({
  email: EmailSchema,
  password: z.string().min(1, 'Password is required'),
});

export type LoginDto = z.infer<typeof LoginSchema>;

// ── Token Refresh ─────────────────────────────────────────────────────────────

export const RefreshTokenSchema = z.object({
  refreshToken: z.string().min(1, 'Refresh token is required'),
});

export type RefreshTokenDto = z.infer<typeof RefreshTokenSchema>;

// ── Password Operations ────────────────────────────────────────────────────────

export const ForgotPasswordSchema = z.object({
  email: EmailSchema,
});

export type ForgotPasswordDto = z.infer<typeof ForgotPasswordSchema>;

export const ResetPasswordSchema = z.object({
  token: z.string().min(1),
  newPassword: PasswordSchema,
});

export type ResetPasswordDto = z.infer<typeof ResetPasswordSchema>;

export const ChangePasswordSchema = z.object({
  currentPassword: z.string().min(1, 'Current password is required'),
  newPassword: PasswordSchema,
});

export type ChangePasswordDto = z.infer<typeof ChangePasswordSchema>;

// ── Email Verification ─────────────────────────────────────────────────────────

export const VerifyEmailSchema = z.object({
  token: z.string().min(1, 'Verification token is required'),
});

export type VerifyEmailDto = z.infer<typeof VerifyEmailSchema>;

// ── Auth Responses ─────────────────────────────────────────────────────────────

export type AuthTokensResponse = {
  accessToken: string;
  refreshToken: string;
  expiresIn: number; // seconds until access token expires
  tokenType: 'Bearer';
};

export type AuthUserResponse = {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  companyId: string | null;
  emailVerifiedAt: Date | null;
  avatarUrl: string | null;
};

export type LoginResponse = {
  user: AuthUserResponse;
  tokens: AuthTokensResponse;
};

import { createModuleLogger } from '@/core/logger.js';
import { AuthDomainError } from '@/shared/errors/DomainError.js';
import {
  UnauthorizedError,
  ConflictError,
  NotFoundError,
} from '@/shared/errors/index.js';

import type { User } from '../../domain/entities/User.entity.js';
import type { IUserRepository } from '../../domain/repositories/IUserRepository.js';
import type {
  LoginDto,
  LoginResponse,
  RegisterCandidateDto,
} from '../dtos/auth.dto.js';
import type { IJwtService } from '../interfaces/IJwtService.js';
import type { IPasswordService } from '../interfaces/IPasswordService.js';
import type { ISessionService } from '../interfaces/ISessionService.js';

const log = createModuleLogger('LoginUseCase');

/**
 * Login Use Case.
 *
 * Application layer: Orchestrates domain objects and infrastructure services.
 * Contains NO business rules — only workflow coordination.
 * Contains NO database code — delegates to repository interfaces.
 * Contains NO HTTP concerns — returns domain objects, not HTTP responses.
 */
export class LoginUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly passwordService: IPasswordService,
    private readonly jwtService: IJwtService,
    private readonly sessionService: ISessionService,
  ) {}

  async execute(dto: LoginDto): Promise<LoginResponse> {
    log.info({ email: dto.email }, 'Login attempt');

    // Find user
    const user = await this.userRepository.findByEmail(dto.email);
    if (user === null) {
      // Deliberate: same error for "not found" and "wrong password"
      // Prevents email enumeration attacks
      throw new UnauthorizedError('Invalid email or password', 'AUTH_INVALID_CREDENTIALS');
    }

    // Check account status
    if (user.status === 'SUSPENDED') {
      throw new UnauthorizedError('Account suspended. Contact support.', 'AUTH_ACCOUNT_SUSPENDED');
    }

    if (user.isLocked()) {
      throw new AuthDomainError(
        'AUTH_ACCOUNT_NOT_FOUND',
        `Account temporarily locked. Try again after ${user.lockedUntil?.toISOString()}.`,
      );
    }

    // Verify password
    if (user.passwordHash === null) {
      // OAuth-only account — no password set
      throw new UnauthorizedError(
        'This account uses social login. Please sign in with Google or GitHub.',
        'AUTH_INVALID_CREDENTIALS',
      );
    }

    const isPasswordValid = await this.passwordService.verify(dto.password, user.passwordHash);

    if (!isPasswordValid) {
      // Increment login attempts
      await this.userRepository.incrementLoginAttempts(user.id);
      log.warn({ userId: user.id }, 'Invalid password attempt');
      throw new UnauthorizedError('Invalid email or password', 'AUTH_INVALID_CREDENTIALS');
    }

    // Reset login attempts on success
    await this.userRepository.resetLoginAttempts(user.id);
    await this.userRepository.updateLastLogin(user.id, ''); // IP filled by caller

    // Create session
    const sessionId = await this.sessionService.createSession(user.id);

    // Generate tokens
    const tokens = await this.jwtService.generateTokenPair(user, sessionId);

    log.info({ userId: user.id, sessionId }, 'Login successful');

    return {
      user: {
        id: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        role: user.role,
        companyId: user.companyId ?? null,
        emailVerifiedAt: user.emailVerifiedAt,
        avatarUrl: user.avatarUrl,
      },
      tokens,
    };
  }
}

/**
 * Register Candidate Use Case.
 */
export class RegisterCandidateUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly passwordService: IPasswordService,
    private readonly jwtService: IJwtService,
    private readonly sessionService: ISessionService,
  ) {}

  async execute(dto: RegisterCandidateDto): Promise<LoginResponse> {
    log.info({ email: dto.email }, 'Candidate registration');

    // Check email uniqueness
    const existing = await this.userRepository.findByEmail(dto.email);
    if (existing !== null) {
      throw new ConflictError('An account with this email already exists', 'AUTH_EMAIL_ALREADY_EXISTS');
    }

    // Hash password
    const passwordHash = await this.passwordService.hash(dto.password);

    // Create user + candidate profile in transaction
    const user = await this.userRepository.createCandidate({
      email: dto.email,
      passwordHash,
      firstName: dto.firstName,
      lastName: dto.lastName,
    });

    // Create session
    const sessionId = await this.sessionService.createSession(user.id);

    // Generate tokens
    const tokens = await this.jwtService.generateTokenPair(user, sessionId);

    log.info({ userId: user.id }, 'Candidate registered successfully');

    return {
      user: {
        id: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        role: user.role,
        companyId: null,
        emailVerifiedAt: user.emailVerifiedAt,
        avatarUrl: user.avatarUrl,
      },
      tokens,
    };
  }
}

/**
 * Refresh Token Use Case.
 */
export class RefreshTokenUseCase {
  constructor(
    private readonly jwtService: IJwtService,
    private readonly sessionService: ISessionService,
    private readonly userRepository: IUserRepository,
  ) {}

  async execute(refreshToken: string): Promise<{ accessToken: string; expiresIn: number }> {
    // Verify refresh token
    const payload = await this.jwtService.verifyRefreshToken(refreshToken);

    // Verify session is still valid
    const isSessionValid = await this.sessionService.isSessionValid(
      payload.sub,
      payload.sessionId,
    );

    if (!isSessionValid) {
      throw new UnauthorizedError('Session expired. Please log in again.', 'AUTH_REFRESH_TOKEN_INVALID');
    }

    // Get current user (role may have changed)
    const user = await this.userRepository.findById(payload.sub);
    if (user === null) {
      throw new UnauthorizedError('User not found', 'AUTH_ACCOUNT_NOT_FOUND');
    }

    // Issue new access token (refresh token stays the same)
    const { accessToken, expiresIn } = await this.jwtService.generateAccessToken(
      user,
      payload.sessionId,
    );

    return { accessToken, expiresIn };
  }
}

/**
 * Logout Use Case.
 */
export class LogoutUseCase {
  constructor(private readonly sessionService: ISessionService) {}

  async execute(userId: string, sessionId: string): Promise<void> {
    await this.sessionService.revokeSession(userId, sessionId);
    log.info({ userId, sessionId }, 'User logged out');
  }
}

/**
 * Logout All Sessions Use Case.
 */
export class LogoutAllSessionsUseCase {
  constructor(private readonly sessionService: ISessionService) {}

  async execute(userId: string): Promise<void> {
    await this.sessionService.revokeAllSessions(userId);
    log.info({ userId }, 'All sessions revoked');
  }
}

