import jwt from 'jsonwebtoken';

import { config } from '@/core/config.js';
import { UnauthorizedError } from '@/shared/errors/index.js';

import type { AuthTokensResponse } from '../../application/dtos/auth.dto.js';
import type { IJwtService } from '../../application/interfaces/IJwtService.js';

/**
 * JWT service — signs and verifies access and refresh tokens.
 *
 * Access token: short-lived (15min), contains full user context
 * Refresh token: long-lived (7d), contains only userId + sessionId
 *
 * Both tokens use HS256 with separate secrets — if refresh secret
 * is compromised, access tokens remain valid only for 15min max.
 */
export class JwtService implements IJwtService {
  private readonly accessSecret = config.JWT_ACCESS_SECRET;
  private readonly refreshSecret = config.JWT_REFRESH_SECRET;
  private readonly issuer = config.JWT_ISSUER;
  private readonly audience = config.JWT_AUDIENCE;

  async generateTokenPair(
    user: { id: string; email: string; role: string; companyId?: string | null },
    sessionId: string,
  ): Promise<AuthTokensResponse> {
    const { accessToken, expiresIn } = await this.generateAccessToken(user, sessionId);
    const refreshToken = this.signRefreshToken(user.id, sessionId);

    return {
      accessToken,
      refreshToken,
      expiresIn,
      tokenType: 'Bearer',
    };
  }

  async generateAccessToken(
    user: { id: string; email: string; role: string; companyId?: string | null },
    sessionId: string,
  ): Promise<{ accessToken: string; expiresIn: number }> {
    const expiresIn = 15 * 60; // 15 minutes in seconds

    const accessToken = jwt.sign(
      {
        email: user.email,
        role: user.role,
        companyId: user.companyId ?? null,
        sessionId,
      },
      this.accessSecret,
      {
        subject: user.id,
        expiresIn,
        issuer: this.issuer,
        audience: this.audience,
        algorithm: 'HS256',
      },
    );

    return { accessToken, expiresIn };
  }

  private signRefreshToken(userId: string, sessionId: string): string {
    return jwt.sign(
      { sessionId },
      this.refreshSecret,
      {
        subject: userId,
        expiresIn: '7d',
        issuer: this.issuer,
        audience: this.audience,
        algorithm: 'HS256',
      },
    );
  }

  async verifyAccessToken(token: string): Promise<{
    sub: string;
    email: string;
    role: string;
    companyId: string | null;
    sessionId: string;
  }> {
    try {
      const payload = jwt.verify(token, this.accessSecret, {
        issuer: this.issuer,
        audience: this.audience,
        algorithms: ['HS256'],
      }) as jwt.JwtPayload;

      return {
        sub: payload['sub'] as string,
        email: payload['email'] as string,
        role: payload['role'] as string,
        companyId: (payload['companyId'] as string | null) ?? null,
        sessionId: payload['sessionId'] as string,
      };
    } catch (error) {
      if (error instanceof jwt.TokenExpiredError) {
        throw new UnauthorizedError('Access token expired', 'AUTH_TOKEN_EXPIRED');
      }
      throw new UnauthorizedError('Invalid access token', 'AUTH_TOKEN_INVALID');
    }
  }

  async verifyRefreshToken(token: string): Promise<{ sub: string; sessionId: string }> {
    try {
      const payload = jwt.verify(token, this.refreshSecret, {
        issuer: this.issuer,
        audience: this.audience,
        algorithms: ['HS256'],
      }) as jwt.JwtPayload;

      return {
        sub: payload['sub'] as string,
        sessionId: payload['sessionId'] as string,
      };
    } catch (error) {
      if (error instanceof jwt.TokenExpiredError) {
        throw new UnauthorizedError('Refresh token expired. Please log in again.', 'AUTH_REFRESH_TOKEN_INVALID');
      }
      throw new UnauthorizedError('Invalid refresh token', 'AUTH_REFRESH_TOKEN_INVALID');
    }
  }
}

import { authMiddleware } from '@/middleware/auth.middleware.js';
import { validate } from '@/middleware/validate.middleware.js';
import { ResponseFormatter } from '@/shared/response/ResponseFormatter.js';

import {
  RegisterCompanyOwnerSchema
} from '../application/dtos/auth.dto.js';

import type {
  LoginSchema,
  RegisterCandidateSchema,
  RefreshTokenSchema} from '../application/dtos/auth.dto.js';
import type {
  LoginUseCase,
  RegisterCandidateUseCase,
  RefreshTokenUseCase,
  LogoutUseCase,
} from '../application/use-cases/auth.usecase.js';
import type { Request, Response, NextFunction } from 'express';



/**
 * Auth Controller — presentation layer.
 *
 * Responsibilities:
 * - Parse and validate HTTP request (delegate to validate middleware)
 * - Call the appropriate use case
 * - Format the response
 *
 * Controllers MUST NOT contain business logic.
 * Controllers MUST NOT make direct DB calls.
 * Controllers are thin adapters between HTTP and application layer.
 */
export class AuthController {
  constructor(
    private readonly loginUseCase: LoginUseCase,
    private readonly registerCandidateUseCase: RegisterCandidateUseCase,
    private readonly refreshTokenUseCase: RefreshTokenUseCase,
    private readonly logoutUseCase: LogoutUseCase,
  ) {}

  login = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const result = await this.loginUseCase.execute(req.body as ReturnType<typeof LoginSchema.parse>);
      ResponseFormatter.success(res, result);
    } catch (error) {
      next(error);
    }
  };

  registerCandidate = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const result = await this.registerCandidateUseCase.execute(
        req.body as ReturnType<typeof RegisterCandidateSchema.parse>,
      );
      ResponseFormatter.created(res, result);
    } catch (error) {
      next(error);
    }
  };

  refreshToken = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const { refreshToken } = req.body as ReturnType<typeof RefreshTokenSchema.parse>;
      const result = await this.refreshTokenUseCase.execute(refreshToken);
      ResponseFormatter.success(res, result);
    } catch (error) {
      next(error);
    }
  };

  logout = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      if (req.user === undefined) {
        ResponseFormatter.noContent(res);
        return;
      }
      await this.logoutUseCase.execute(req.user.id, req.user.sessionId);
      ResponseFormatter.noContent(res);
    } catch (error) {
      next(error);
    }
  };

  me = (req: Request, res: Response): void => {
    ResponseFormatter.success(res, req.user);
  };
}

import { AuditAction } from '@microintern/shared';
import { Router } from 'express';

import { getContainer } from '@/core/container.js';
import { audit } from '@/middleware/audit.middleware.js';
import { authMiddleware } from '@/middleware/auth.middleware.js';
import { authRateLimiter } from '@/middleware/ratelimit.middleware.js';
import { validate } from '@/middleware/validate.middleware.js';

import {
  LoginSchema,
  RegisterCandidateSchema,
  RefreshTokenSchema,
} from '../application/dtos/auth.dto.js';

import type { AuthController } from './auth.controller.js';
import type { ApplicationContainer } from '@/core/container.js';

/**
 * Auth router factory.
 * Creates controller with dependencies from container.
 */
export function createAuthRouter(): Router {
  const container = getContainer();
  const controller = container.get<AuthController>('AuthController');

  const router = Router();

  // POST /auth/register/candidate
  router.post(
    '/register/candidate',
    authRateLimiter,
    validate('body', RegisterCandidateSchema),
    audit(AuditAction.REGISTER, 'User'),
    (req, res, next) => { controller.registerCandidate(req, res, next).catch(next); },
  );

  // POST /auth/login
  router.post(
    '/login',
    authRateLimiter,
    validate('body', LoginSchema),
    audit(AuditAction.LOGIN, 'User'),
    (req, res, next) => { controller.login(req, res, next).catch(next); },
  );

  // POST /auth/refresh
  router.post(
    '/refresh',
    validate('body', RefreshTokenSchema),
    (req, res, next) => { controller.refreshToken(req, res, next).catch(next); },
  );

  // POST /auth/logout
  router.post(
    '/logout',
    authMiddleware,
    audit(AuditAction.LOGOUT, 'User'),
    (req, res, next) => { controller.logout(req, res, next).catch(next); },
  );

  // GET /auth/me
  router.get(
    '/me',
    authMiddleware,
    (req, res) => { controller.me(req, res); },
  );

  return router;
}
